Rules.InvariantScript:
// Count the number of rows in the BookingListCollection where the BookingDate is Today 
CountRows(
    Filter(
        BookingpListCollection,
        DateValue(Text(Créé, "[$-en-US]yyyy-mm-dd")) = Today()
    )
)

// Count the number of rows in the BookingListCollection where the BookingStatus is "Cancelled" 
// and the Modified date is today
CountRows(
    Filter(
        BookingpListCollection,
        BookingStatus.Value = "Cancelled" && 
        // Compare only the date part of the 'Modified' column with today's date to handle potential datatype mismatches
        DateValue(Text(Modifié, "[$-en-US]yyyy-mm-dd")) = Today()
    )
)

// Filter the BookingListCollection based in the logged in USer and various criteria and sort the results
SortByColumns(
    Filter(
        BookingpListCollection,
        Requestor.Email = User().Email && 
        // Partial match for BookedCarID and BookedCarName using Txt_Filter_Dashboard_Search
        (IsBlank(Txt_Filter_Dashboard_Search_1.Text) ||
         // Check if BookedCarID starts with the search text
 StartsWith(
            Text(BookedCarID),
            Txt_Filter_Dashboard_Search_1.Text
        ) ||
         // Check if BookingPickupLocation starts with the search text
 StartsWith(
            Text(BookingPickupLocation),
            Txt_Filter_Dashboard_Search_1.Text
        ) ||
         // Check if BookingDropoffLocation starts with the search text
 StartsWith(
            Text(BookingDropoffLocation),
            Txt_Filter_Dashboard_Search_1.Text
        ) ||
         // Check if BookedCarName starts with the search text
 StartsWith(
            BookedCarName,
            Txt_Filter_Dashboard_Search_1.Text
        )),
        // Filter by BookingStatus (Choice column) using the collection
        (IsBlank(SelectedBookingStatus) ||
         // Check if the BookingStatus exists in the selected statuses
 CountRows(
            Filter(
                SelectedBookingStatus,
                Value = BookingStatus.Value
            )
        ) > 0),
        // Filter by BookingPurpose (Choice column) using the collection
        (IsBlank(SelectedBookingPurpose) ||
         // Check if the BookingPurpose exists in the selected purposes
 CountRows(
            Filter(
                SelectedBookingPurpose,
                Value = BookingPurpose.Value
            )
        ) > 0),
        // Filter by date range
        (IsBlank(DatePickerFrom_Filter_MyBooking_DateRange.SelectedDate) || IsBlank(DatePickerTo_Filter_MyBooking_DateRange.SelectedDate) ||
         // Check if BookingDate is within the selected date range
 (BookingDate >= DatePickerFrom_Filter_MyBooking_DateRange.SelectedDate && BookingDate <= DatePickerTo_Filter_MyBooking_DateRange.SelectedDate))
    ),
    // Sort by the Created date in descending order to show the latest entries first
    "Created",
    SortOrder.Descending
)

UpdateContext({ ShowLoader: true });
