Rules.InvariantScript:
// Bouton de suppression
UpdateContext({ConfirmationPopup: true});
Set(RecordToDelete, VarRecord);  // Stocke l'enregistrement à supprimer

If(
    Not(IsBlank(LookUp(SelectedBookingPurpose, Value = ThisItem.Value))),
    // Item is already in the collection, so remove it
    Remove(
        SelectedBookingPurpose,
        LookUp(SelectedBookingPurpose, Value = ThisItem.Value)
    ),
    // Item is not in the collection, so add it
    Collect(
        SelectedBookingPurpose,
        ThisItem
    )
)

If(
    Not(IsBlank(LookUp(SelectedBookingStatus, Value = ThisItem.Value))),
    // Item is already in the new collection, so remove it
    Remove(
        SelectedBookingStatus,
        LookUp(SelectedBookingStatus, Value = ThisItem.Value)
    );
    ,
    // Item is not in the new collection, so add it
    Collect(
        SelectedBookingStatus,
        ThisItem
    )
)

If(
    Not(IsBlank(LookUp(SelectedBookingStatus, Value = ThisItem.Value))),
    // Item is selected
    If(
        ThisItem.Value = "Best Practice",
        RGBA(48, 194, 27, 1), // Color for "Booked"
        If(
            ThisItem.Value = "Negative Lesson",
            RGBA(251, 25, 25, 1), // Color for "Cancelled"
            Parent.Fill // Default color if the status is neither "Booked" nor "Cancelled"
        )
    ),
    // Item is not selected
    RGBA(44, 44, 44, 1) // Default color when not selected
)

