Reset(Txt_Filter_Dashboard_Search_1);
Reset(DatePickerFrom_Filter_Dashboard_DateRange_1);
Reset(DatePickerTo_Filter_Dashboard_DateRange_1);
// Populate SelectedBookingPurpose with default options from the BookingPurpose choice column
ClearCollect(
    SelectedBookingPurpose,
    Choices('Booking pList'.BookingPurpose)
);

// Populate SelectedBookingStatus with default options from the BookingStatus choice column
ClearCollect(
    SelectedBookingStatus,
    Choices('Booking pList'.BookingStatus)
);

